const fs = require('fs');
const path = require('path');
const file = path.join(__dirname, '..', '.copilot', 'repo', 'agents-pipeline.md');
const oldBlock = '## Loop root cause (bug fixed)\nAgent repeated similar tool calls (grep/read oscillation) and never called \u0060runTests\u0060; old guard only caught *identical consecutive* calls (\u0060lastCallKey\u0060/\u0060consecutiveIdentical\u0060, SPIN_LIMIT=2) — oscillation slipped through and burned all 12 turns, leaving "Tests were not run by the agent — verify manually".';
const newBlock = '## Loop hardening in \u0060src/agents/implement.ts\u0060 (v3.9.0, 2026-02)\nThree layers stop the implementer from burning all 12 turns without running tests:\n1. **Windowed spin guard** (\u0060SPIN_WINDOW=4\u0060, \u0060EDIT_TOOL_NAMES\u0060): suppresses exact repeats (A,A,A — 3rd call) AND oscillation (A,B,A,B — repeat with no edit in between). Repeats around a real edit tool are legitimate re-reads and allowed.\n2. **Deadline nudge**: at \u0060turn >= MAX_TURNS - 2\u0060 with no test run, injects a user message forcing \u0060runTests\u0060 + conclude.\n3. **Safety-net test run**: if the loop exits (cap OR conclusion) with \u0060!ranTests\u0060, the pipeline invokes \u0060runTests\u0060 itself once so the report carries a real verdict — never "verify manually". \u0060testsPassed\u0060 from \u0060/pass/i && !/fail/i\u0060.\n\nConclusion path: text-only reply breaks the loop; trusts \u0060/tests? (?:pass|passed)/i\u0060 only when \u0060!ranTests\u0060.\n\n## Loop root cause (the bug that motivated this)\nAgent repeated similar tool calls (grep/read oscillation) and never called \u0060runTests\u0060; old guard only caught *identical consecutive* calls (\u0060lastCallKey\u0060/\u0060consecutiveIdentical\u0060, SPIN_LIMIT=2), so oscillation slipped through and burned all 12 turns.';
let content = fs.readFileSync(file, 'utf8');
if (!content.includes(oldBlock)) { console.error('anchor not found'); console.log(content); process.exit(1); }
content = content.replace(oldBlock, newBlock);
content = content.replace('139/139 (21 files)', '143/143 (21 files)');
content = content.replace('~420KB', '~422KB');
fs.writeFileSync(file, content);
console.log('memory updated');
